import {renderCategorySpending,renderPlanChanges} from './budget-insights.js';
import {themeColor} from './theme.js';
import {createPlanPaymentsUI} from './plan-payments-ui.js';
import {euro,fieldMoney,money,monthName,projected,currentMonth,validDate,resolveExpensePlan} from './planner.js';
import {parseCSV,guessColumns,previewCSV,importEntries,reconcileMonth,saveEntryClassification,closeMonth,reopenMonth} from './reconciliation.js';
export function createReconciliationUI(ctx){
 const {esc,btn}=ctx;const payments=createPlanPaymentsUI(ctx);let categoryFilter='',listKind='all',listStatus='all',chartMode='spent',filterMonth='',unlinkedOnly=false;let fileText='',parsed=null,header=0,mapping=null,draft=[],page=0,importRevision=null;
 const close=()=>document.querySelector('#dialog').close(),options=(list,value)=>list.map(([v,t])=>`<option value="${v}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`).join(''),foot=label=>`<div class="form-footer"><button type="button" class="btn btn-outline" data-action="close">Abbrechen</button><button type="submit" class="btn btn-primary">${label}</button></div>`;
 function form(title,html,fn){const revision=ctx.state.revision;ctx.openDialog(title,`<form>${html}</form>`,f=>{if(revision!==ctx.state.revision)throw Error('Der Stand hat sich geändert. Bitte erneut öffnen.');fn(new FormData(f));});}
 async function handleFile(file){if(!file)return;if(file.size>5000000)throw Error('Bitte eine Datei bis 5 MB wählen.');const bytes=await file.arrayBuffer();fileText=new TextDecoder('utf-8').decode(bytes);if(fileText.includes('\uFFFD'))fileText=new TextDecoder('windows-1252').decode(bytes);parsed=parseCSV(fileText);if(parsed.rows.length<2)throw Error('Die Datei enthält keine Umsätze mit Kopfzeile.');header=0;draft=[];importRevision=ctx.state.revision;fileSetup();}
 function fileSetup(){form('CSV vorbereiten',`<p class="helper">Die Datei wird ausschließlich hier auf Deinem Gerät gelesen. Es werden keine Bankdaten hochgeladen.</p><div class="form-grid spaced"><label><span>Trennzeichen</span><select name="delimiter">${options([[';','Semikolon'],[',','Komma'],['tab','Tabulator']],parsed.delimiter==='\t'?'tab':parsed.delimiter)}</select></label><label><span>Zeile mit Spaltennamen</span><input name="header" type="number" min="1" max="${parsed.rows.length}" value="${header+1}" required></label></div><div class="csv-sample">${parsed.rows.slice(0,5).map((r,i)=>`<p><b>${i+1}</b> ${esc(r.join(' · ').slice(0,240))}</p>`).join('')}</div>${foot('Spalten zuordnen')}`,fd=>{parsed=parseCSV(fileText,fd.get('delimiter')==='tab'?'\t':fd.get('delimiter'));header=Number(fd.get('header'))-1;if(!parsed.rows[header])throw Error('Die Kopfzeile existiert nicht.');mapping=guessColumns(parsed.rows[header]);mapForm();});}
 function mapForm(){const cols=[[-1,'Nicht vorhanden'],...parsed.rows[header].map((h,i)=>[i,h||'Spalte '+(i+1)])],select=(key,label)=>`<label><span>${label}</span><select name="${key}">${options(cols,mapping[key])}</select></label>`;form('Spalten zuordnen',`<div class="form-grid">${select('date','Buchungsdatum')}${select('title','Händler / Empfänger / Name')}${select('details','Verwendungszweck (optional)')}${select('amount','Betrag')}${select('debit','Soll (bei getrennten Beträgen)')}${select('credit','Haben (bei getrennten Beträgen)')}${select('currency','Währung (optional)')}<label><span>Betragsart</span><select name="mode">${options([['signed','Minus = Ausgabe · Plus = Einnahme'],['expenses','Alle Beträge sind Ausgaben'],['split','Getrennte Soll- und Haben-Spalten']],mapping.mode)}</select></label><label><span>Dezimalzeichen</span><select name="decimal">${options([['comma','Komma · 1.234,56'],['dot','Punkt · 1,234.56']],mapping.decimal)}</select></label></div><p class="helper spaced">Bitte die Vorschau prüfen. Ohne Währungsspalte werden Eurobeträge angenommen. Wiedererkannte Händler übernehmen Deine bestätigte Kategorie und Art.</p>${foot('Importvorschau anzeigen')}`,fd=>{for(const k of ['date','title','details','amount','debit','credit','currency'])mapping[k]=Number(fd.get(k));mapping.mode=fd.get('mode');mapping.decimal=fd.get('decimal');draft=previewCSV(ctx.state,parsed.rows.slice(header+1),mapping);page=0;importRevision=ctx.state.revision;preview();});}
 function preview(){const selected=draft.filter(r=>r.selected&&!r.error),errors=draft.filter(r=>r.error),duplicates=draft.filter(r=>r.duplicate),visible=draft.slice(page*20,page*20+20),pages=Math.ceil(draft.length/20);ctx.openDialog('Umsätze vor dem Import prüfen',`<div class="import-summary"><strong>${selected.length} ausgewählt</strong><span>${duplicates.length} mögliche Duplikate · ${errors.length} fehlerhafte Zeilen</span></div><p class="helper">Duplikatverdacht ist zunächst abgewählt. Wähle einen solchen Umsatz nur aus, wenn es tatsächlich eine weitere Buchung ist. Einnahmen und Umbuchungen zählen nicht als Konsumausgaben.</p><div class="inline spaced"><button class="textbtn" data-action="csv-new-only">Neue auswählen</button><button class="textbtn" data-action="csv-none">Alle abwählen</button><button class="textbtn" data-action="csv-map">Spalten ändern</button></div><div class="import-rows">${visible.map(r=>r.error?`<div class="import-row invalid"><strong>Zeile ${header+2+r.row-1}</strong><span>${esc(r.error)}</span></div>`:`<article class="import-row ${r.selected?'selected':''}"><button class="import-pick" data-action="csv-toggle" data-id="${r.id}" aria-pressed="${r.selected}" aria-label="${esc(r.title)} auswählen">${r.selected?'✓':'＋'}</button><div><strong>${esc(r.title)}</strong><span>${r.date} · ${{expense:'Ausgabe',income:'Einnahme',transfer:'Umbuchung'}[r.kind]} · ${esc(ctx.state.categories.find(c=>c.id===r.category)?.name||'')}${r.planItemId?' · Planposten: '+esc(ctx.state.items.find(i=>i.id===r.planItemId)?.title||''):''}</span>${r.duplicate?'<small class="negative">Mögliches Duplikat</small>':''}</div><b>${euro(r.amount)}</b><button class="textbtn" data-action="csv-edit" data-id="${r.id}">Prüfen</button></article>`).join('')}</div><div class="import-pages"><button class="btn btn-outline" data-action="csv-prev" ${page===0?'disabled':''}>Zurück</button><span>${page+1} / ${Math.max(1,pages)}</span><button class="btn btn-outline" data-action="csv-next" ${page+1>=pages?'disabled':''}>Weiter</button></div><p class="helper">Ausgewählte fehlerfreie Umsätze werden gespeichert; fehlerhafte Zeilen werden ausgelassen. Planposten und Rücklagenstände bleiben beim Import unverändert.</p><div class="form-footer"><button class="btn btn-outline" data-action="csv-cancel">Abbrechen</button><button class="btn btn-primary" data-action="csv-commit" ${selected.length?'':'disabled'}>${selected.length} Umsätze importieren</button></div>`);}
 function classification(id,isDraft=false){const x=isDraft?draft.find(r=>r.id===id):ctx.state.actualExpenses.find(r=>r.id===id);if(!x)throw Error('Dieser Umsatz fehlt.');if(!isDraft&&ctx.state.monthClosures.some(c=>c.month===x.date.slice(0,7)))throw Error('Bitte den Monatsabschluss zuerst zurücknehmen.');const plan=projected(ctx.state,x.date.slice(0,7)).filter(i=>i.type==='expense');form('Umsatz zuordnen',`<div class="reconcile-entry-heading"><strong>${esc(x.title)}</strong><span>${x.date} · ${euro(x.amount)}</span></div><label class="spaced"><span>Name</span><input name="title" value="${esc(x.title)}" maxlength="160" required></label><div class="form-grid spaced"><label><span>Betrag (€)</span><input name="amount" inputmode="decimal" value="${fieldMoney(x.amount)}" required></label><label><span>Datum</span><input name="date" type="date" value="${x.date}" min="2000-01-01" max="2100-12-31" required></label><label><span>Art</span><select name="kind">${options([['expense','Ausgabe'],['income','Einnahme / Erstattung'],['transfer','Umbuchung zwischen eigenen Konten']],x.kind||'expense')}</select></label><label><span>Kategorie</span><select name="category">${options(ctx.state.categories.map(c=>[c.id,c.name]),x.category)}</select></label><label><span>Richtung einer Umbuchung</span><select name="direction">${options([['out','Vom Konto zum Rücklagentopf'],['in','Aus dem Rücklagentopf zum Konto']],x.direction||'out')}</select></label><label><span>Topf bei Umbuchung (optional)</span><select name="potId">${options([['','Kein Topf / anderes eigenes Konto'],...ctx.state.pots.map(p=>[p.id,p.name])],x.potId||'')}</select></label></div><label class="spaced"><span>Gehört zu diesem Ausgaben-Planposten</span><select name="planItemId">${options([['','Ohne Zuordnung zum Planposten'],...plan.map(i=>[i.id,i.title+' · '+euro(i.monthlyAmount)])],resolveExpensePlan(ctx.state,plan,x)?.id||'')}</select></label><p class="helper spaced">Mehrere Käufe können zu einem Planposten gehören. Umbuchungen werden nur im Umsatzjournal gekennzeichnet; eine geplante Topfbewegung wird dadurch nicht doppelt gebucht. Bei einer Erstattung bleibt die ursprüngliche Ausgabe bestehen, die Erstattung zählt als Einnahme.</p>${!isDraft?'<label class="scenario-check"><input name="learn" type="checkbox" value="yes" checked><span>Art und Kategorie für diesen Händlernamen merken</span></label>':''}${foot(isDraft?'In Vorschau übernehmen':'Zuordnung speichern')}`,fd=>{const fields={title:String(fd.get('title')||'').trim(),amount:money(fd.get('amount')),date:fd.get('date'),kind:fd.get('kind'),category:fd.get('category'),direction:fd.get('direction'),planItemId:fd.get('planItemId')||'',potId:fd.get('potId')||'',learn:fd.get('learn')==='yes'};if(!fields.title||!validDate(fields.date)||!fields.amount)throw Error('Bitte Name, Datum und einen Betrag größer als null prüfen.');if(!isDraft&&ctx.state.monthClosures.some(c=>c.month===fields.date.slice(0,7)))throw Error('Bitte den Monatsabschluss zuerst zurücknehmen.');if(fields.kind!=='expense')fields.planItemId='';if(fields.kind!=='transfer')fields.potId='';if(isDraft){Object.assign(x,fields);preview();}else if(ctx.persist(saveEntryClassification(ctx.state,id,fields),'Umsatz zugeordnet'))close();});}
 function journalRows(r){const entries=[...r.entries].filter(x=>(!unlinkedOnly||r.unlinked.some(u=>u.id===x.id))&&(!categoryFilter||(r.links.find(i=>i.payments.some(p=>p.id===x.id))?.category||x.category)===categoryFilter)).sort((a,b)=>b.date.localeCompare(a.date));let last='';return entries.map(x=>{const cat=ctx.state.categories.find(c=>c.id===(r.links.find(i=>i.payments.some(p=>p.id===x.id))?.category||x.category)),day=x.date!==last?`<h3 class="journal-day">${new Date(x.date+'T12:00:00').toLocaleDateString('de-DE',{day:'numeric',month:'long',weekday:'short'})}</h3>`:'';last=x.date;return `${day}<article class="unified-entry"><button data-action="reconcile-edit" data-id="${x.id}"><i style="background:${themeColor(cat?.color||'#4b5660')}"></i><span><strong>${esc(x.title)}</strong><small>${esc(cat?.name||'')} · ${{expense:r.links.some(i=>i.payments.some(p=>p.id===x.id))?'Im Budget erfasst':'Ohne Planzuordnung',income:'Einnahme / Erstattung',transfer:'Umbuchung'}[x.kind||'expense']}</small></span><b>${euro(x.amount)}</b></button><button class="iconbtn" data-action="actual-delete" data-id="${x.id}" aria-label="${esc(x.title)} löschen">${ctx.icon('trash')}</button></article>`;}).join('')||'<p class="quiet-empty">Noch keine Zahlungen für diese Auswahl.</p>';}
 function render(){if(filterMonth!==ctx.month){categoryFilter='';listKind='all';listStatus='all';unlinkedOnly=false;filterMonth=ctx.month;}const r=reconcileMonth(ctx.state,ctx.month),closure=ctx.state.monthClosures.find(c=>c.month===ctx.month);return `<div class="unified-spending">${payments.render(r,{filter:categoryFilter,kind:listKind,status:listStatus})}${renderPlanChanges(ctx.state,ctx.month,esc)}${renderCategorySpending(r,esc,chartMode,categoryFilter)}<section class="spending-journal" id="spending-journal"><div class="section-head"><div><h2>Erfasste Zahlungen</h2><p>${categoryFilter?esc(ctx.state.categories.find(c=>c.id===categoryFilter)?.name||''):unlinkedOnly?'Ohne Planzuordnung':'Alle Einträge dieses Monats'} · Antippen zum Bearbeiten</p></div><button class="textbtn" data-action="actual-csv">CSV</button></div>${categoryFilter||unlinkedOnly?'<button class="filter-chip" data-action="spending-clear">Alle Zahlungen zeigen ×</button>':''}<div id="spending-journal-rows">${journalRows(r)}</div></section><details class="spending-tools"><summary>Import & Monatsabschluss</summary><div class="inline spaced">${btn('CSV importieren','csv-start','outline','plus')}<input id="csv-picker" type="file" accept=".csv,text/csv,text/plain" hidden></div>${closure?`<section class="scenario-verdict ${closure.signature!==r.signature?'is-warning':''}"><strong>Monat abgeschlossen · ${euro(closure.available)} übertragen</strong><p>${closure.signature!==r.signature?'Der Stand wurde seit dem Abschluss geändert. Bitte erneut prüfen.':'Der bestätigte Restbetrag ist im Folgemonat eingeplant.'}</p><button class="textbtn" data-action="month-reopen">Abschluss zurücknehmen</button></section>`:`<div class="inline spaced">${btn('Monat abschließen','month-close','primary','check')}<p class="helper">Erst wenn Einnahmen, Ausgaben und Rücklagenbewegungen vollständig geprüft sind.</p></div>`}</details></div>`;}
 function scroll(id){document.querySelector(id)?.scrollIntoView?.({behavior:'smooth',block:'start'});}
 function flow(key){const r=reconcileMonth(ctx.state,ctx.month);if(key==='spent'){categoryFilter='';unlinkedOnly=false;ctx.render();scroll('#spending-journal');return;}if(key==='bills'||key==='budgets'){categoryFilter='';listKind=key==='bills'?'fixed':'variable';listStatus='open';ctx.render();scroll('#spending-posts');return;}const items=projected(ctx.state,ctx.month).filter(i=>key==='withdrawals'?i.type==='income'&&i.potId:key==='saving'?i.type==='saving':false);ctx.openDialog(key==='withdrawals'?'Aus Deinen Rücklagen':key==='saving'?'Sparen & Rücklagen':'Dein freier Betrag',items.length?`<div class="flow-item-list">${items.map(i=>`<button data-action="edit-item" data-id="${i.id}"><span>${esc(i.title)}<small>${esc(ctx.state.pots.find(p=>p.id===i.potId)?.name||'')}</small></span><b>${euro(i.monthlyAmount)}</b></button>`).join('')}</div>`:`<dl class="flow-details">${[['Einnahmen',r.budgetIncome],['Aus Rücklagen',r.reserveWithdrawals],['Bereits ausgegeben',-r.actualTotal],['Sparen & Rücklagen geplant',-r.plannedSaving],['Rechnungen offen',-r.fixedOpen],['Variable Budgets übrig',-r.variableOpen],['Frei verfügbar',r.afterOpen]].map(([label,value])=>`<div><dt>${label}</dt><dd>${euro(value)}</dd></div>`).join('')}</dl><p class="helper spaced">Geplante Einnahmen und erfasste Ausgaben. Kein Kontostand.</p>`);}
 function monthClose(){if(ctx.month>currentMonth())throw Error('Ein zukünftiger Monat kann noch nicht abgeschlossen werden.');const r=reconcileMonth(ctx.state,ctx.month);form('Monatsabschluss · '+monthName(ctx.month),`<p class="helper">Bestätige die tatsächlichen Gesamtbeträge. Fehlende Buchungen gelten nicht als Ersparnis. Ein- und Auszahlungen zwischen eigenen Girokonten gehören nicht in diese Summen. Der Anfangsrest enthält den vorgeschlagenen Übertrag aus dem Vormonat; prüfe ihn und zähle geschützte Rücklagen nicht dazu.</p><div class="form-grid spaced"><label><span>Verfügbarer Rest zu Monatsbeginn (€)</span><input name="opening" inputmode="decimal" value="${fieldMoney(r.opening)}" required></label><label><span>Tatsächliche Einnahmen inkl. Erstattungen (€)</span><input name="income" inputmode="decimal" value="${fieldMoney(r.income)}" required></label><label><span>Tatsächlich in Rücklagen eingezahlt (€)</span><input name="deposits" inputmode="decimal" value="${fieldMoney(r.deposits)}" required></label><label><span>Tatsächlich aus Rücklagen entnommen (€)</span><input name="withdrawals" inputmode="decimal" value="${fieldMoney(r.withdrawals)}" required></label></div><p class="helper spaced">Erfasste Konsumausgaben: <strong>${euro(r.actualTotal)}</strong>. Rest = Anfangsrest + Einnahmen + Entnahmen − Einzahlungen − Ausgaben.</p><label class="spaced"><span>Davon in einen Topf / ein Ziel (€)</span><input name="assigned" inputmode="decimal" value="0,00" required></label><label class="spaced"><span>Zieltopf</span><select name="potId">${options([['','Rest im Folgemonat frei lassen'],...ctx.state.pots.map(p=>[p.id,p.name+(ctx.state.goals.find(g=>g.potId===p.id&&g.status==='active')?' · '+ctx.state.goals.find(g=>g.potId===p.id&&g.status==='active').title:'')])],'')}</select></label><label class="scenario-check spaced"><input type="checkbox" name="confirmed" value="yes" required><span>Alle Ausgaben sind erfasst; Einnahmen und Rücklagenbewegungen sind vollständig geprüft.</span></label>${foot('Übertrag prüfen')}`,fd=>{const values={opening:money(fd.get('opening')),income:money(fd.get('income')),deposits:money(fd.get('deposits')),withdrawals:money(fd.get('withdrawals')),assigned:money(fd.get('assigned')),potId:fd.get('potId')||'',confirmed:fd.get('confirmed')==='yes'},raw=values.opening+values.income+values.withdrawals-values.deposits-r.actualTotal;closeMonth(ctx.state,ctx.month,values);form('Übertrag bestätigen',`<div class="close-total"><span>Bestätigter Restbetrag</span><strong>${euro(raw)}</strong></div><p class="helper spaced">${raw<0?'Es besteht ein Fehlbetrag. Es wird kein positiver Rest übertragen.':'Davon '+euro(values.assigned)+' in den ausgewählten Topf und '+euro(raw-values.assigned)+' frei im Folgemonat.'}</p><p class="helper spaced">Der Übertrag ist vorhandenes Geld, kein neuer Verdienst. Der Monatsabschluss lässt sich später zurücknehmen, solange die erzeugten Posten unverändert sind.</p>${foot('Abschluss speichern')}`,()=>{if(ctx.persist(closeMonth(ctx.state,ctx.month,values),'Monatsabschluss gespeichert'))close();});});}
 return {render,handleFile,paymentPreview:payments.preview,actions:{...payments.actions,'spending-category':el=>{categoryFilter=categoryFilter===el.dataset.id?'':el.dataset.id;listKind='all';listStatus='all';unlinkedOnly=false;ctx.render();scroll('#spending-posts');},'spending-status':el=>{listStatus=el.dataset.id;ctx.render();scroll('#spending-posts');},'spending-mode':el=>{chartMode=el.dataset.id;ctx.render();},'spending-clear':()=>{categoryFilter='';listKind='all';listStatus='all';unlinkedOnly=false;ctx.render();},'spending-unlinked':()=>{categoryFilter='';unlinkedOnly=true;ctx.render();scroll('#spending-journal');},'spending-flow':el=>flow(el.dataset.id),'csv-start':()=>{document.querySelector('#csv-picker').value='';document.querySelector('#csv-picker').click();},'csv-map':mapForm,'csv-prev':()=>{page=Math.max(0,page-1);preview();},'csv-next':()=>{page=Math.min(Math.ceil(draft.length/20)-1,page+1);preview();},'csv-toggle':el=>{const r=draft.find(r=>r.id===el.dataset.id);if(r&&!r.error)r.selected=!r.selected;preview();},'csv-edit':el=>classification(el.dataset.id,true),'csv-new-only':()=>{draft.forEach(r=>r.selected=!r.error&&!r.duplicate);preview();},'csv-none':()=>{draft.forEach(r=>r.selected=false);preview();},'csv-cancel':()=>{draft=[];fileText='';close();},'csv-commit':()=>{if(importRevision!==ctx.state.revision)throw Error('Der Stand hat sich geändert. Bitte die Importvorschau neu erzeugen.');const selected=draft.filter(r=>r.selected&&!r.error);if(!selected.length)return;const n=importEntries(ctx.state,draft);if(ctx.commitUndo(n,selected.length+' Umsätze importiert')){draft=[];fileText='';close();}},'reconcile-edit':el=>classification(el.dataset.id),'month-close':monthClose,'month-reopen':()=>{const revision=ctx.state.revision;ctx.confirmDialog('Abschluss zurücknehmen?','Die unveränderten Übertragsposten im Folgemonat werden entfernt. Erfasste Umsätze bleiben erhalten.',()=>{if(revision!==ctx.state.revision)throw Error('Der Stand hat sich geändert.');if(ctx.persist(reopenMonth(ctx.state,ctx.month),'Monat wieder geöffnet'))close();},'Zurücknehmen');}}};
}
